class CertificateIssueException extends RuntimeException { private $status; private $validation; public function __construct(string $m,int $s=422,array $v=[]){parent::__construct($m);$this->status=$s;$this->validation=$v;} public function httpStatus():int{return $this->status;} public function validation():array{return $this->validation;} }
function certificate_hex_rgb(string $h):array{$v=ltrim($h,'#');if(strlen($v)===3){$v=$v[0].$v[0].$v[1].$v[1].$v[2].$v[2];}if(!preg_match('/^[0-9a-f]{6}$/i',$v)){$v='000000';}return ['r'=>hexdec(substr($v,0,2)),'g'=>hexdec(substr($v,2,2)),'b'=>hexdec(substr($v,4,2))];}
function certificate_color($im,string $h):int{$c=certificate_hex_rgb($h);return imagecolorallocate($im,$c['r'],$c['g'],$c['b']);}
function certificate_font_candidates(bool $b=false):array{$root=dirname(__DIR__,2);$font=($b?'DejaVuSans-Bold.ttf':'DejaVuSans.ttf');$a=[$root.'/public/fonts/'.$font,$root.'/fonts/'.$font];$a[]=DIRECTORY_SEPARATOR==='\\'?'C:\\Windows\\Fonts\\'.($b?'arialbd.ttf':'arial.ttf'):'/usr/share/fonts/truetype/dejavu/'.($b?'DejaVuSans-Bold.ttf':'DejaVuSans.ttf');return array_values(array_unique($a));}
function certificate_find_font(bool $b=false):?string{foreach(certificate_font_candidates($b) as $f){if(is_file($f))return $f;}return null;}
function certificate_text_width(string $t,int $s,?string $f):int{if($f&&function_exists('imagettfbbox')){$b=imagettfbbox($s,0,$f,$t);return (int)abs($b[2]-$b[0]);}return (int)(strlen($t)*$s*.55);}
function certificate_wrap_text(string $t,int $w,int $s,?string $f):array{$o=[];foreach(preg_split('/\R/',trim($t))?:[] as $p){$l='';foreach(preg_split('/\s+/',trim($p))?:[] as $word){$n=$l===''?$word:$l.' '.$word;if($l!==''&&certificate_text_width($n,$s,$f)>$w){$o[]=$l;$l=$word;}else{$l=$n;}}$o[]=$l;}return $o?:[''];}
function certificate_draw_text($im,string $t,int $x,int $y,int $s,string $h,?string $f,string $a='left'):void{if(!$f||!is_file($f)||!function_exists('imagettftext')||!function_exists('imagettfbbox'))throw new RuntimeException('Certificate font or FreeType support is unavailable.');$c=certificate_color($im,$h);$w=certificate_text_width($t,$s,$f);if($a==='center')$x-=(int)($w/2);elseif($a==='right')$x-=$w;imagettftext($im,$s,0,$x,$y,$c,$f,$t);}
function certificate_create_jpeg_pdf(string $path,string $jpg):void{$data=file_get_contents($jpg);if($data===false)throw new RuntimeException('Unable to read certificate image.');$i=getimagesize($jpg);$w=(int)$i[0];$h=(int)$i[1];$o=["1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj\n","2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 >> endobj\n","3 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /XObject << /Im0 5 0 R >> >> /Contents 4 0 R >> endobj\n"];$stream='q 595 0 0 842 0 0 cm /Im0 Do Q';$o[]="4 0 obj << /Length ".strlen($stream)." >> stream\n$stream\nendstream endobj\n";$o[]="5 0 obj << /Type /XObject /Subtype /Image /Width $w /Height $h /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ".strlen($data)." >> stream\n$data\nendstream endobj\n";$pdf="%PDF-1.4\n%\xE2\xE3\xCF\xD3\n";$off=[0];foreach($o as $v){$off[]=strlen($pdf);$pdf.=$v;}$x=strlen($pdf);$pdf.="xref\n0 6\n0000000000 65535 f \n";for($n=1;$n<=5;$n++)$pdf.=sprintf('%010d 00000 n ',$off[$n])."\n";$pdf.="trailer << /Size 6 /Root 1 0 R >>\nstartxref\n$x\n%%EOF";if(file_put_contents($path,$pdf)===false)throw new RuntimeException('Unable to archive PDF.');@unlink($jpg);}
function normalize_certificate_number($v):string{$v=trim((string)$v);if($v===''||strlen($v)>100||preg_match('/[\x00-\x1f\x7f]/',$v))throw new CertificateIssueException('Certificate number is invalid.',422,['certificate_number'=>'Enter a valid certificate number.']);return $v;}
function write_certificate_qr_svg(string $path,string $url):void{$qr=QRCode::getMinimumQRCode($url,QR_ERROR_CORRECT_LEVEL_M);$n=$qr->getModuleCount();$q=4;$m=8;$z=($n+8)*$m;$r='';for($y=0;$y<$n;$y++)for($x=0;$x<$n;$x++)if($qr->isDark($y,$x))$r.='<rect x="'.(($x+$q)*$m).'" y="'.(($y+$q)*$m).'" width="'.$m.'" height="'.$m.'"/>';file_put_contents($path,'<svg xmlns="http://www.w3.org/2000/svg" width="'.$z.'" height="'.$z.'"><rect width="100%" height="100%" fill="white"/><g>'.$r.'</g></svg>');}
function certificate_build_payload(array $i,array $rows,array $att,string $no,int $rev,string $verify,string $issued,string $expiry,string $finger):array{$f=[];foreach($rows as $r)$f[(string)$r['field_key']]=trim((string)($r['value_text']??''));global $config;return ['fields'=>$f,'certificate_number'=>$no,'revision'=>$rev,'verification_url'=>$verify,'issue_date'=>$issued,'expiry_date'=>$expiry,'client_name'=>(string)$i['client_name'],'equipment_name'=>(string)$i['equipment_name'],'asset_code'=>(string)$i['asset_code'],'category_name'=>(string)$i['category_name'],'inspector_name'=>(string)$i['inspector_name'],'company_name'=>(string)$config['company_name']];}
function write_certificate_pdf(string $path,array $p):void{$im=imagecreatetruecolor(1654,2339);imagefilledrectangle($im,0,0,1654,2339,certificate_color($im,'#fff'));$f=certificate_find_font(false);$b=certificate_find_font(true)?:$f;certificate_draw_text($im,$p['company_name'],827,170,38,'#111',$b,'center');certificate_draw_text($im,'CERTIFICATE OF INSPECTION',827,280,34,'#111',$b,'center');$y=400;foreach(['CERTIFICATE NUMBER: '.$p['certificate_number'],'REVISION: '.$p['revision'],'CLIENT: '.$p['client_name'],'EQUIPMENT: '.$p['asset_code'].' - '.$p['equipment_name'],'INSPECTION TYPE: '.$p['category_name'],'ISSUE DATE: '.$p['issue_date'],'EXPIRY DATE: '.$p['expiry_date'],'INSPECTOR: '.$p['inspector_name']] as $l){certificate_draw_text($im,$l,180,$y,23,'#111',$f);$y+=55;}$jpg=preg_replace('/\.pdf$/i','.jpg',$path)?:$path.'.jpg';imagejpeg($im,$jpg,92);imagedestroy($im);certificate_create_jpeg_pdf($path,$jpg);}
