status']??'valid'),'expires_at'=>$expiry,'revoked_at'=>$old['revoked_at']??null]);lever_hoist_render_certificate_pdf($pp,$p);}elseif($family==='flat_webbing_sling'){flat_webbing_sling_validate($i,$rows,$no,$issued,$expiry,$attachments,(int)($i['requires_evidence']??0)===1,(int)($i['minimum_evidence_files']??0));$p=flat_webbing_sling_payload($i,$rows,$no,$rev,$verify,$issued,$expiry);$p['authentication']=$auth;$p['status']=!empty($input['create_revision'])?'valid':certificate_effective_status(['status'=>(string)($old['status']??'valid'),'expires_at'=>$expiry,'revoked_at'=>$old['revoked_at']??null]);flat_webbing_sling_render_certificate_pdf($pp,$p);}elseif($family==='eye_bolt'){eye_bolt_validate($i,$rows,$items,$no,$issued,$expiry);$p=eye_bolt_payload($i,$rows,$items,$no,$rev,$verify,$issued,$expiry);$p['authentication']=$auth;$p['status']=!empty($input['create_revision'])?'valid':certificate_effective_status(['status'=>(string)($old['status']??'valid'),'expires_at'=>$expiry,'revoked_at'=>$old['revoked_at']??null]);eye_bolt_render_certificate_pdf($pp,$p);}elseif($family==='hook'){hook_validate($i,$rows,$items,$no,$issued,$expiry);$p=hook_payload($i,$rows,$items,$no,$rev,$verify,$issued,$expiry);$p['authentication']=$auth;$p['status']=!empty($input['create_revision'])?'valid':certificate_effective_status(['status'=>(string)($old['status']??'valid'),'expires_at'=>$expiry,'revoked_at'=>$old['revoked_at']??null]);hook_render_certificate_pdf($pp,$p);}elseif($family==='general_lifting_accessory'){general_lifting_accessory_validate($i,$rows,$items,$no,$issued,$expiry);$p=general_lifting_accessory_payload($i,$rows,$items,$no,$rev,$verify,$issued,$expiry);$p['authentication']=$auth;$p['status']=!empty($input['create_revision'])?'valid':certificate_effective_status(['status'=>(string)($old['status']??'valid'),'expires_at'=>$expiry,'revoked_at'=>$old['revoked_at']??null]);general_lifting_accessory_render_certificate_pdf($pp,$p);}elseif($family==='general_thorough_examination'){general_thorough_examination_validate($i,$rows,$no,$issued,$expiry,$attachments,(int)($i['requires_evidence']??0)===1,(int)($i['minimum_evidence_files']??0));$p=general_thorough_examination_payload($i,$rows,$no,$rev,$verify,$issued,$expiry);$p['authentication']=$auth;$p['status']=!empty($input['create_revision'])?'valid':certificate_effective_status(['status'=>(string)($old['status']??'valid'),'expires_at'=>$expiry,'revoked_at'=>$old['revoked_at']??null]);general_thorough_examination_render_certificate_pdf($pp,$p);}elseif($family==='mpi_spreader_bar'){mpi_spreader_bar_validate($i,$rows,$no,$issued,$expiry,$attachments,(int)($i['requires_evidence']??0)===1,(int)($i['minimum_evidence_files']??0));$p=mpi_spreader_bar_payload($i,$rows,$no,$rev,$verify,$issued,$expiry);$p['authentication']=$auth;$p['status']=!empty($input['create_revision'])?'valid':certificate_effective_status(['status'=>(string)($old['status']??'valid'),'expires_at'=>$expiry,'revoked_at'=>$old['revoked_at']??null]);mpi_spreader_bar_render_certificate_pdf($pp,$p);}else{$p=certificate_build_payload($i,$rows,[],$no,$rev,$verify,$issued,$expiry,$finger);write_certificate_pdf($pp,$p);}$hash=hash_file('sha256',$pp);
