id,$rev,$old?'revision_issued':'certificate_issued');if(!empty($notification['ids'])){audit_log((int)$user['id'],'notifications.queued','certificate',$id,['revision'=>$rev,'recipients'=>count($notification['ids'])]);foreach($notification['ids'] as $notificationId)send_notification((int)$notificationId,(int)$user['id']);}
