function issue_certificate(array $user, int $inspectionId, array $input = [], array $options = []): array
{
    $lockName = 'juva_cert_issue_' . $inspectionId;
    $stmt = db()->prepare('SELECT GET_LOCK(?, 10)');
    $stmt->execute([$lockName]);
    if ((int) $stmt->fetchColumn() !== 1) {
        throw new CertificateIssueException('Certificate issuance is already in progress. Wait a moment and retry.', 409);
    }
    try {
        return issue_certificate_unlocked($user, $inspectionId, $input, $options);
    } finally {
        $release = db()->prepare('SELECT RELEASE_LOCK(?)');
        $release->execute([$lockName]);
    }
}
